//! Generates the Tauri context and, from the app manifest, one `allow-<command>` permission per
//! `kiln_*` IPC command, so `capabilities/*.json` can grant exactly these commands.
//! `menu.json` (the native menus) is generated by `pnpm --filter @kiln/commands desktop:menu`.
fn main() {
    println!("cargo:rerun-if-changed=menu.json");
    let manifest = tauri_build::AppManifest::new().commands(&[
        "kiln_open",
        "kiln_new",
        "kiln_execute",
        "kiln_query",
        "kiln_viewport",
        "kiln_frame",
        "kiln_a11y",
        "kiln_subscribe",
        "kiln_host_reply",
        "kiln_startup_probe",
        "kiln_home_painted",
        "kiln_window_context",
        "kiln_close_window",
        "kiln_open_paths",
        "kiln_open_route",
        "kiln_clipboard_text",
        "kiln_share",
        "kiln_leave",
    ]);
    if let Err(e) = tauri_build::try_build(tauri_build::Attributes::new().app_manifest(manifest)) {
        // A build script reports failure by panicking; the message is what Cargo shows.
        panic!("tauri-build failed: {e:#}");
    }
}
